function validate(input) {
  const [{ Elements = [] }] = input;
  const types = ['Metal', 'Nonmetal', 'Noble'];
  const seen = new Set();
  for (const [symbol, type, electrons] of Elements) {
    if (symbol === null || type === null || electrons === null) return 'symbol, type and electrons are required.';
    const key = String(symbol).toLowerCase();
    if (seen.has(key)) return `symbol ${symbol} appears twice in Elements.`;
    seen.add(key);
    if (!types.includes(type)) return `Unknown type ${type}.`;
    if (electrons < 0) return `${symbol} has a negative electron count.`;
    if (type === 'Noble' && electrons !== 0) return `Noble element ${symbol} must have 0 electrons.`;
  }
  return null;
}

