function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const upper = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', lower = upper.toLowerCase();
  // Symbols look like real ones: one capital letter, optionally followed by a small letter.
  const pool = [...upper];
  for (const a of upper) for (const b of lower) pool.push(a + b);
  for (let i = pool.length - 1; i > 0; i--) { const j = pick(i + 1); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  const count = size === 'small' ? pick(9) : 200;
  const types = ['Metal', 'Nonmetal', 'Noble'];
  const Elements = [];
  for (let i = 0; i < count; i++) {
    const type = types[pick(3)];
    Elements.push([pool[i], type, type === 'Noble' ? 0 : 1 + pick(4)]);
  }
  return [{ Elements }];
}
